// Quarto toggles `quarto-light` / `quarto-dark` on &lt;body&gt;. Watch the class
// list rather than the toggle button, so this survives any future change to
// the navbar markup, and so it also picks up the initial state on load.
theme = Generators.observe(notify =&gt; {
  const body = document.body;
  const read = () =&gt; body.classList.contains("quarto-dark") ? "dark" : "light";
  notify(read());
  const observer = new MutationObserver(() =&gt; notify(read()));
  observer.observe(body, {attributes: true, attributeFilter: ["class"]});
  return () =&gt; observer.disconnect();
})
// One source of truth for colour: the palette is declared in styles.css and
// read back here, rather than restating the hex in JS where it could drift.
// `theme` is referenced purely to make this cell recompute on every toggle.
palette = {
  theme;
  const cs = getComputedStyle(document.body);
  const v = name =&gt; cs.getPropertyValue(name).trim();
  return {
    cotton: v("--ccr-cotton"),
    rubber: v("--ccr-rubber"),
    brent: v("--ccr-brent"),
    fg: v("--ccr-fg"),
    muted: v("--ccr-muted"),
    line: v("--ccr-line")
  };
}

Observed prices

// `month` arrives as a Date, not a string: d3.autoType matches "2026-01"
// against its ISO-date regex and parses it as UTC midnight. Every scale and
// formatter here is therefore UTC — a local-time axis would label every point
// one month early in any negative-offset timezone.
recent = prices.filter(d =&gt; d.month &gt;= new Date(Date.UTC(2015, 0, 1)))







anchor = {
  const lm = meta.commodities.cotton.last_month; // a string; JSON gets no autoType
  return new Date(Date.UTC(+lm.slice(0, 4), +lm.slice(5, 7) - 1, 1));
}







Plot.plot({
