// Port of src/modeling/backtest.py::backtest_savings. Walk the months in
// order; on an alarm, buy `horizon` months at today's price and jump forward,
// otherwise buy one month. Returns the fraction of spend avoided.
backtestSavings = function (rows, alarmOf, horizon) {
  const px = rows.map(d =&gt; priceByMonth.get(+d.month));
  if (px.some(p =&gt; p === undefined)) return NaN;

  const baseCost = d3.sum(px);
  let alarmCost = 0, i = 0;
  while (i &lt; rows.length) {
    if (alarmOf(rows[i])) {
      const nMonths = Math.min(horizon, rows.length - i);
      alarmCost += nMonths * px[i];
      i += nMonths;
    } else {
      alarmCost += px[i];
      i += 1;
    }
  }
  return 1 - alarmCost / baseCost;
}







